// Locally bundled PDF dependencies; imported data never leaves the browser.
const loads=new Map();
function script(src){if(!loads.has(src))loads.set(src,new Promise((resolve,reject)=>{const s=document.createElement('script');s.src=src;s.onload=resolve;s.onerror=()=>{loads.delete(src);s.remove();reject(new Error('PDF library failed to load'));};document.head.append(s);}));return loads.get(src);}
export async function exportPdf({title,filename,lang='en',elements=[],appendix=''}){
 await Promise.all([script('/vendor/jspdf.umd.min.js'),script('/vendor/html2canvas.min.js')]);
 const frame=document.createElement('iframe');frame.style.cssText='position:fixed;left:-10000px;top:0;width:794px;height:1123px;border:0';frame.setAttribute('aria-hidden','true');document.body.append(frame);
 try{
  const doc=frame.contentDocument;doc.open();doc.write('<!doctype html><html><head><meta charset="utf-8"></head><body></body></html>');doc.close();doc.documentElement.lang=lang;
  for(const style of document.querySelectorAll('link[rel="stylesheet"],style'))doc.head.append(style.cloneNode(true));
  const css=doc.createElement('style');css.textContent='*{box-sizing:border-box}body{margin:0;background:#fff;color:#1b2a3a;font:15px/1.55 Arial,"PingFang SC","Microsoft YaHei",sans-serif}.pdf-block{width:794px;padding:30px 40px;background:#fff;overflow:visible} .pdf-block button,.pdf-block input,.pdf-block iframe,.pdf-block nav,.pdf-block .export,.pdf-block footer{display:none!important}.pdf-block *{max-width:100%;overflow-wrap:anywhere}.pdf-block [hidden]{display:none!important}.pdf-block table{width:100%;font-size:12px;border-collapse:collapse}.pdf-block td,.pdf-block th{white-space:normal;border-bottom:1px solid #ddd;padding:6px}.pdf-block svg{max-width:100%}.pdf-block .analysis-layout,.pdf-block .result-layout,.pdf-block .supporting-grid,.pdf-block #analysis-cards,.pdf-block .terminal-body,.pdf-block .workspace,.pdf-block .comparison-grid{display:block!important}.pdf-block .geometry-card{margin-bottom:16px}.pdf-block header{position:static;height:auto}.pdf-block .sidebar,.pdf-block .watch{display:none!important}';doc.head.append(css);
  const blocks=[];const add=node=>{const b=doc.createElement('section');b.className='pdf-block';b.append(node);doc.body.append(b);blocks.push(b);};
  const heading=doc.createElement('div');const h=doc.createElement('h1');h.textContent=title;heading.append(h);const date=doc.createElement('p');date.textContent=new Date().toLocaleString(lang==='zh'?'zh-CN':'en-US');heading.append(date);add(heading);
  for(const el of elements.filter(Boolean)){const clone=el.cloneNode(true);clone.removeAttribute('hidden');clone.querySelectorAll('button,input,iframe,nav,.language,.lang').forEach(n=>n.remove());add(clone);}
  if(appendix){const content=doc.createElement('div');content.innerHTML=appendix;for(const node of [...content.children]){if(node.tagName==='TABLE'){const rows=[...node.querySelectorAll('tbody tr')];for(let i=0;i<rows.length;i+=24){const table=doc.createElement('table');const head=node.querySelector('thead');if(head)table.append(head.cloneNode(true));const body=doc.createElement('tbody');rows.slice(i,i+24).forEach(r=>body.append(r.cloneNode(true)));table.append(body);add(table);}}else add(node);}}
  await Promise.all([...doc.querySelectorAll('link')].map(l=>l.sheet?Promise.resolve():new Promise(r=>{l.onload=r;l.onerror=r;})));await doc.fonts.ready;
  const pdf=new window.jspdf.jsPDF({unit:'mm',format:'a4',compress:true});pdf.setProperties({title,creator:'SecondOrder'});let page=0;
  for(const block of blocks){const canvas=await window.html2canvas(block,{scale:1.5,backgroundColor:'#fff',logging:false,windowWidth:794,scrollX:0,scrollY:0});const max=Math.floor(canvas.width*267/190);let y=0;
   while(y<canvas.height){let height=Math.min(max,canvas.height-y);if(y+height<canvas.height){const ctx=canvas.getContext('2d',{willReadFrequently:true});for(let cut=height;cut>height-60;cut--){const row=ctx.getImageData(0,y+cut-1,canvas.width,1).data;let ink=0;for(let i=0;i<row.length;i+=4)if(row[i]<235||row[i+1]<235||row[i+2]<235)ink++;if(ink<4){height=cut;break;}}}
    const slice=doc.createElement('canvas');slice.width=canvas.width;slice.height=height;slice.getContext('2d').drawImage(canvas,0,y,canvas.width,height,0,0,canvas.width,height);if(page++)pdf.addPage();pdf.addImage(slice.toDataURL('image/jpeg',.94),'JPEG',10,10,190,height/canvas.width*190);pdf.setFontSize(9);pdf.text('SecondOrder · '+page,10,290);y+=height;slice.width=0;slice.height=0;
   }canvas.width=0;canvas.height=0;
  }const blob=pdf.output('blob');const previous=document.getElementById('prepared-pdf');if(previous){URL.revokeObjectURL(previous.href);previous.remove();}const link=document.createElement('a');link.id='prepared-pdf';link.href=URL.createObjectURL(blob);link.download=filename.endsWith('.pdf')?filename:filename+'.pdf';link.textContent=lang==='zh'?'下载 PDF':'Download PDF';link.style.cssText='position:fixed;right:24px;bottom:24px;z-index:1000;background:white;border:1px solid #243e72;padding:12px;color:#243e72';document.body.append(link);link.click();
 }finally{frame.remove();}
}
export function dataAppendix(data,lang='en'){
 const esc=v=>String(v??'—').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const render=v=>Array.isArray(v)?v.length&&typeof v[0]==='object'&&v[0]!==null&&!Array.isArray(v[0])?'<table><thead><tr>'+Object.keys(v[0]).map(k=>'<th>'+esc(k)+'</th>').join('')+'</tr></thead><tbody>'+v.map(r=>'<tr>'+Object.keys(v[0]).map(k=>'<td>'+esc(typeof r[k]==='object'?JSON.stringify(r[k]):r[k])+'</td>').join('')+'</tr>').join('')+'</tbody></table>':'<p>'+esc(JSON.stringify(v))+'</p>':v&&typeof v==='object'?Object.entries(v).map(([k,x])=>'<h3>'+esc(k)+'</h3>'+render(x)).join(''):'<p>'+esc(v)+'</p>';
 return '<h2>'+(lang==='zh'?'完整结果与审计记录':'Complete results and audit record')+'</h2>'+render(data);
}
